from model8 import Q,R,load,dump,METHODS,choices
import csv,json,datetime,hashlib

def main():
 designs=load(Q/'rtl/design_manifest.json');ppa=load(Q/'results/hardware/ppa.json')if(Q/'results/hardware/ppa.json').exists()else[];by={r['top']:r for r in ppa};inh={x['case']:x for x in load(Q/'state/inherited_results.json')};ee={e['top']:e for e in designs};assert len(ppa)==sum(not e['duplicate_of']and not e['inherited_physical']for e in designs);rows=[];cases=[]
 for e in designs:
  target=ee[e['duplicate_of']or e['top']];old=target['inherited_physical'];p=inh[e['case']]['physical_result']if old else by[target['top']];v=next(r for r in csv.DictReader((Q/f'results/{e["case"]}_verify.csv').open())if r['method']==e['method']);assert int(v['seed_max_delta'])==0 and int(v['WCE'])<=e['budget'];row=dict(case=e['case'],method=e['method'],source_round=inh[e['case']]['source_round']if old else 8,new_physical_run=not old,**{k:p[k]for k in ['LUT','FF','CARRY4','DSP','clock_ns','WNS_ns','WHS_ns','FF_period_ns','pass_registered_clock','wall_s']},WCE=int(v['WCE']),seed_max_delta=int(v['seed_max_delta']),inputs=int(v['inputs']),physical_top=p['top'],reused_identical_rtl=bool(e['duplicate_of']));rows.append(row)
 for c in load(Q/'configs/plan.json')['cases']:
  n=c['name'];rr={r['method']:r for r in rows if r['case']==n};ps=load(Q/f'graphs/{n}_pairs.json');replay=list(csv.DictReader((Q/f'results/{n}_replay.csv').open()));accepted={m:[dict(pair=i,candidate_class=ps[i]['candidate_class'],fanin_a=len(ps[i]['a_ins']),fanin_b=len(ps[i]['b_ins']),union=ps[i]['union'])for i,k in choices(n,m)]for m in METHODS[1:]};eligible=[m for m in METHODS[:2]if rr[m]['pass_registered_clock']];best=min(eligible,key=lambda m:rr[m]['LUT'])if eligible else None
  cases.append(dict(case=n,starting_method=c['starting_method'],LUT={m:r['LUT']for m,r in rr.items()},WNS_ns={m:r['WNS_ns']for m,r in rr.items()},gain_vs_seed_pct=100*(rr['seed']['LUT']-rr['relation']['LUT'])/rr['seed']['LUT'],gain_vs_local_pct=100*(rr['local_exact']['LUT']-rr['relation']['LUT'])/rr['local_exact']['LUT'],gain_vs_best_passing_baseline_pct=100*(rr[best]['LUT']-rr['relation']['LUT'])/rr[best]['LUT']if best and rr['relation']['pass_registered_clock']else None,timing_pass={m:r['pass_registered_clock']for m,r in rr.items()},output_functions_identical=True,pool=load(Q/f'state/{n}_pool.json'),optimization=load(Q/f'state/{n}_optimize.json'),accepted_pairs=accepted,replay_scans=len(replay),replay_inputs=sum(int(r['inputs'])for r in replay)))
 a=dict(round=8,status='COMPLETE_AWAIT_SCORE',completed=datetime.datetime.now().astimezone().isoformat(),rows=rows,cases=cases,full_domain_final_scans=len(rows),effective_final_inputs_evaluated=sum(r['inputs']for r in rows),new_physical_jobs=len(ppa),inherited_seed_jobs=len(inh),hdl=load(Q/'state/rtl_validation.json'),engineering_repairs=load(Q/'state/engineering_repairs.json'),limits=['strongest tested ABC input does not mean every literature SOTA','fixed candidate pools and topology search, no global optimality','small arithmetic cores; same output and clocks, not application speedup']);assert len(a['hdl'])==6
 dump(Q/'state/analysis.json',a)
 with(Q/'reports/RESULTS.csv').open('w',newline='')as f:w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
 hashes={p.relative_to(Q).as_posix():hashlib.sha256(p.read_bytes()).hexdigest()for sub in ['tools','configs','src','rtl','graphs','results','build']for p in(Q/sub).rglob('*')if p.is_file()and p.suffix in['.py','.tcl','.json','.cpp','.v','.sv','.xdc','.csv','.hex','.log','.rpt','.stderr']};dump(Q/'state/evidence_hashes.json',hashes);print(json.dumps(cases,indent=2))
